css:
@page {
	size: A4 portrait;
	margin: 15mm 15mm 15mm 20mm;
}

.sb-zm {
	color: #000;
	font-size: 9pt;
	line-height: 1.35;
}

.sb-zm h1 {
	font-size: 15pt;
	font-weight: 600;
	margin: 0 0 1mm;
}

.sb-zm h2 {
	font-size: 10.5pt;
	font-weight: 600;
	margin: 6mm 0 2mm;
}

.sb-zm .sb-subtitle {
	color: #444;
	font-weight: 600;
	margin: 0 0 3mm;
}

.sb-zm table {
	width: 100%;
	border-collapse: collapse;
}

.sb-zm thead {
	display: table-header-group;
}

.sb-zm tr,
.sb-zm .sb-group {
	break-inside: avoid;
	page-break-inside: avoid;
}

.sb-zm .sb-head {
	margin: 3mm 0 5mm;
}

.sb-zm .sb-label,
.sb-zm .sb-value {
	padding: 0.8mm 2mm 0.8mm 0;
	text-align: left;
	vertical-align: top;
}

.sb-zm .sb-label {
	color: #555;
	white-space: nowrap;
	width: 58mm;
}

.sb-zm .sb-note {
	color: #444;
	margin: 0 0 4mm;
}

.sb-zm .sb-lines {
	table-layout: fixed;
}

.sb-zm .sb-lines th {
	border-bottom: 0.4mm solid #000;
	font-size: 8pt;
	font-weight: 600;
	padding: 1mm 1.5mm;
	text-align: left;
	vertical-align: bottom;
}

.sb-zm .sb-lines td {
	border-bottom: 0.2mm solid #bbb;
	padding: 1mm 1.5mm;
	vertical-align: top;
}

.sb-zm .sb-lines .sb-section td {
	background: #ececec;
	border-bottom: 0.3mm solid #888;
	font-weight: 600;
	padding-top: 1.8mm;
}

.sb-zm .sb-lines .sb-sum td {
	font-weight: 600;
}

.sb-zm .sb-lines .sb-empty td {
	color: #666;
}

.sb-zm col.sb-id {
	width: 36mm;
}

.sb-zm col.sb-art {
	width: 12mm;
}

.sb-zm col.sb-num {
	width: 34mm;
}

.sb-zm .sb-id {
	white-space: nowrap;
}

.sb-zm .sb-art {
	text-align: center;
}

.sb-zm .sb-num,
.sb-zm .sb-lines th.sb-num {
	text-align: right;
}

.sb-zm td.sb-num {
	white-space: nowrap;
}

.sb-zm .sb-footer {
	border-top: 0.3mm solid #888;
	color: #444;
	font-size: 8pt;
	margin-top: 6mm;
	padding-top: 2mm;
}

.sb-zm .sb-footer p {
	margin: 0 0 1mm;
}
